const STATUS_META = {"burn":{"name":"Brand","desc":"Feuerschaden über Zeit.","emoji":"🔥"},"frost":{"name":"Frost","desc":"Verlangsamt das Angriffstempo des Gegners.","emoji":"❄️"},"shock":{"name":"Schock","desc":"Chance, dass der Gegner aussetzt.","emoji":"⚡"},"poison":{"name":"Gift","desc":"Schaden über Zeit, ignoriert Rüstung. Heilbar mit Antigift.","emoji":"🟢"},"bleed":{"name":"Blutung","desc":"Schaden über Zeit, ignoriert Rüstung.","emoji":"🩸"}};
const DEFENSE_META = {"armor":{"name":"Gepanzert","desc":"Mindert Schaden durch Rüstung. Gekontert durch Rüstungsdurchdringung."},"evasion":{"name":"Flink","desc":"Weicht Treffern komplett aus. Gekontert durch Präzision."},"ward":{"name":"Beschildet","desc":"Schützt Lebenspunkte mit einem Ward-Pool, bevor er durchbricht. Gekontert durch Ward-Durchbruch."}};
const FOREVER_CHASE = {"pastures":"cowhide_jerkin","borderlands":"felmagician_eye","ashfields":"ash_tyrant_crown","blackthorn":"warden_greatcloak","crypt":"nekro_reaperblade","wildwood":"bearhide_cuirass","coast":"abyssal_signet","slagpit":"doomknight_cinderblade","highlands":"voidwing_greatbow","idolhall":"idol_aegis"};
const DUNGEON_NAME_FOR_ZONE = {"idolhall":"Sanktum des Letzten Götzen","borderlands":"Die Goblin-Kriegsbande","wildwood":"Die Wildwald-Jagd"};

function itemImg(id) { return ASSET_BASE + "items/" + id + ".webp"; }
function monsterImg(id) { return ASSET_BASE + "monsters/" + id + ".webp"; }
function eliteImg(id, baseId) { return monsterImg(id); } // alle Champions haben eigene Kunst (geprüft)
function zoneCard(id) { return ASSET_BASE + "battlescreens/" + id + ".card.webp"; }
function zoneFull(id) { return ASSET_BASE + "battlescreens/" + id + ".webp"; }
function itemName(id) { return (ITEM_NAMES[id] && ITEM_NAMES[id].de) || id; }
function itemIcon(id) { return (ITEM_NAMES[id] && ITEM_NAMES[id].icon) || "▪"; }

function fmtNum(n) { return n.toLocaleString("de-DE"); }
function fmtPct(chance) {
  if (chance >= 1) return "100%";
  const pct = chance * 100;
  let digits = chance < 0.01 ? 2 : chance < 0.1 ? 1 : 0;
  if (digits === 2 && Number(pct.toFixed(digits)) === 0) digits = 3;
  return pct.toLocaleString("de-DE", { minimumFractionDigits: digits, maximumFractionDigits: digits }) + "%";
}
function fmtMmSs(ms) {
  const totalSec = Math.max(0, Math.ceil(ms / 1000));
  const m = Math.floor(totalSec / 60);
  const s = totalSec % 60;
  return m + ":" + String(s).padStart(2, "0");
}

/* ─── Spielstand-Simulation ───────────────────────────────────────────────
   3 echte Fortschritts-Profile statt echtem Save — deterministisch berechnet
   (keine Zufallszahlen, damit Screenshots reproduzierbar sind). Jede Zone
   bekommt pro Zustand eine "Reifestufe"; daraus werden Kills, Item-Fund und
   Champion-Sichtungen abgeleitet. */
const STATE_ZONE_PROFILE = {
  early: {
    pastures: "veteran", borderlands: "fresh", ashfields: "none", blackthorn: "none",
    crypt: "none", wildwood: "none", coast: "none", slagpit: "none", highlands: "none", idolhall: "none",
  },
  mid: {
    pastures: "ancient", borderlands: "veteran", ashfields: "veteran", blackthorn: "fresh",
    crypt: "newborn", wildwood: "none", coast: "none", slagpit: "none", highlands: "none", idolhall: "none",
  },
  completionist: {
    pastures: "ancient", borderlands: "ancient", ashfields: "ancient", blackthorn: "ancient",
    crypt: "ancient", wildwood: "veteran", coast: "veteran", slagpit: "veteran", highlands: "fresh", idolhall: "veteran",
  },
};
const STATE_LABELS = { early: "Frühspieler", mid: "Fortgeschritten", completionist: "Completionist" };
const STATE_ORDER = ["early", "mid", "completionist"];

const PROFILE_BASE = { none: 0, newborn: 3, fresh: 45, veteran: 900, ancient: 12000 };
const DISCOVERY_FLOOR = { none: Infinity, newborn: 0.25, fresh: 0.04, veteran: 0.004, ancient: 0.0003 };
const CHAMPION_TIER_DOWN = { ancient: "veteran", veteran: "fresh", fresh: "newborn", newborn: "none", none: "none" };

function killsForMonster(m, profile, rankFraction) {
  if (profile === "none") return 0;
  if (profile === "newborn") return rankFraction < 0.05 ? 3 : rankFraction < 0.18 ? 1 : 0;

  if (m.dungeonOnly) {
    // Raid-artiger Encounter (nur im Dungeon antreffbar, s. DUNGEON_NAME_FOR_ZONE): eigene niedrige
    // Deckelung statt der normalen Zerfallskurve — "frisch" heißt hier "den Dungeon noch nicht
    // gefunden", nicht "0 reguläre Kills".
    return { fresh: 0, veteran: 9, ancient: 24 }[profile] || 0;
  }

  const base = PROFILE_BASE[profile];
  const k = Math.round(base * Math.pow(1 - rankFraction, 1.6));
  // Auch das zäheste reguläre Monster einer gereiften Zone bleibt kein ewiges "???" — Bodenwert
  // statt hartem Zonen-Anker-Nullpunkt (nur "fresh" darf beim stärksten Tier noch bei 0 stehen).
  const floor = { fresh: 0, veteran: 2, ancient: 6 }[profile] || 0;
  return Math.max(k, floor);
}

function deriveChampion(profile) {
  if (profile === "none") return { sightings: 0, kills: 0, uniques: 0, fastestMs: null };
  if (profile === "newborn") return { sightings: 1, kills: 0, uniques: 0, fastestMs: null };
  if (profile === "fresh") return { sightings: 6, kills: 2, uniques: 0, fastestMs: null };
  if (profile === "veteran") return { sightings: 41, kills: 22, uniques: 2, fastestMs: 47200 };
  return { sightings: 312, kills: 281, uniques: 14, fastestMs: 18400 };
}

function buildState(stateKey) {
  const zoneProfiles = STATE_ZONE_PROFILE[stateKey];
  const zoneMonsters = {};
  for (const m of MONSTERS) (zoneMonsters[m.zone] = zoneMonsters[m.zone] || []).push(m);

  const kills = {};
  const discovered = {};
  for (const zoneId of Object.keys(zoneMonsters)) {
    const list = zoneMonsters[zoneId];
    const profile = zoneProfiles[zoneId] || "none";
    list.forEach((m, i) => {
      const rankFraction = list.length <= 1 ? 0 : i / (list.length - 1);
      const k = killsForMonster(m, profile, rankFraction);
      kills[m.id] = k;
      if (k > 0) {
        const floor = DISCOVERY_FLOOR[profile];
        for (const [itemId, chance] of m.loot) {
          if (itemId === FOREVER_CHASE[zoneId]) continue; // Chase-Item bleibt verhüllt
          if (chance >= floor) discovered[itemId] = true;
        }
      }
    });
  }

  const champions = {};
  for (const c of CHAMPIONS) {
    const monsterProfile = zoneProfiles[c.zone] || "none";
    champions[c.id] = deriveChampion(CHAMPION_TIER_DOWN[monsterProfile]);
  }

  const zonesUnlocked = {};
  for (const z of ZONES) zonesUnlocked[z.id] = (zoneProfiles[z.id] || "none") !== "none";

  return { key: stateKey, label: STATE_LABELS[stateKey], kills, discovered, champions, zonesUnlocked };
}

const STATES = {};
for (const key of STATE_ORDER) STATES[key] = buildState(key);

// Gesamt-Item-Katalog-Nenner fürs Kopf-Badge (Discovered: n/total Items) — real ist das der GANZE
// Item-Katalog (>1000), hier bewusst nur die Nenner-Zahl der Studien-Teilmenge referenziert plus ein
// realistischer Gesamt-Offset, damit die Kopfzeile nicht "1/1111" grotesk wirkt bei einer Teilmenge.
const TOTAL_ITEM_CATALOG = 1111;

const ZONE_BY_ID = {};
for (const z of ZONES) ZONE_BY_ID[z.id] = z;

/* ─── Abgeleitete Kartenansicht je Monster/Champion — EINE Logikquelle für alle 5 Konzepte,
   damit jede Studie exakt dieselben Regeln zeigt (Fight-Button-Sperre, Dungeon-Hinweis,
   Drop-Maskierung, Kill-Leiter). Spiegelt BestiaryMonsterCard/ChampionCodex 1:1 (s.
   BestiaryPage.tsx) — nur als reines Datenobjekt statt JSX, jedes Konzept formatiert sein
   eigenes Markup daraus. */
function computeMonsterView(m, stateKey) {
  const st = STATES[stateKey];
  const zone = ZONE_BY_ID[m.zone];
  const kills = st.kills[m.id] || 0;
  const known = kills > 0;
  const zoneLocked = !st.zonesUnlocked[m.zone];

  let fight = { disabled: false, reason: null };
  if (zoneLocked) {
    fight = { disabled: true, reason: 'Erfordert: "' + zone.gate + '"' };
  } else if (m.dungeonOnly) {
    const dName = DUNGEON_NAME_FOR_ZONE[m.zone] || zone.name;
    fight = { disabled: true, reason: "Nur im Dungeon anzutreffen: " + dName };
  }

  const loot = m.loot.map(([itemId, chance]) => {
    const discovered = !!st.discovered[itemId];
    return {
      itemId, chance, discovered,
      pct: fmtPct(chance),
      name: itemName(itemId),
      icon: itemIcon(itemId),
      img: itemImg(itemId),
    };
  });

  const ladder = (m.ladder || []).filter((v, i, arr) => arr.indexOf(v) === i).map((threshold) => ({
    threshold, reached: kills >= threshold,
  }));

  return {
    id: m.id, zoneId: m.zone, zoneName: zone.name, level: m.level, name: m.name,
    img: monsterImg(m.id), known, kills, killsLabel: known ? fmtNum(kills) : "—",
    defenseType: m.dt, defenseName: DEFENSE_META[m.dt].name, defenseDesc: DEFENSE_META[m.dt].desc,
    hp: m.hp, atk: m.atk, def: m.def, regen: m.regen,
    resist: m.resist || [], inflict: m.inflict || null, enrage: !!m.enrage,
    ladder, loot, zoneLocked, dungeonOnly: !!m.dungeonOnly, fight,
  };
}

function computeChampionView(c, stateKey) {
  const st = STATES[stateKey];
  const zone = ZONE_BY_ID[c.zone];
  const entry = st.champions[c.id] || { sightings: 0, kills: 0, uniques: 0, fastestMs: null };
  const known = entry.sightings > 0;
  return {
    id: c.id, zoneId: c.zone, zoneName: zone.name, name: c.name, baseLevel: c.baseLevel,
    img: eliteImg(c.id, null), known,
    sightings: entry.sightings, kills: entry.kills, uniques: entry.uniques,
    fastestLabel: entry.fastestMs != null ? fmtMmSs(entry.fastestMs) : "—",
  };
}

window.BESTIARY = {
  ASSET_BASE, ZONES, MONSTERS, CHAMPIONS, ITEM_NAMES, STATUS_META, DEFENSE_META,
  FOREVER_CHASE, DUNGEON_NAME_FOR_ZONE, STATES, STATE_LABELS, STATE_ORDER, TOTAL_ITEM_CATALOG,
  itemImg, monsterImg, eliteImg, zoneCard, zoneFull, itemName, itemIcon, fmtNum, fmtPct, fmtMmSs,
  computeMonsterView, computeChampionView,
};
